"""Stage 4 (LLM variant): workflow_spec.json -> ASL, generated by a
language model instead of asl_service.generate_asl()'s deterministic
translator.

Opt-in only -- see APISettings.asl_generation_mode (ASL_GENERATION_MODE
env var) in api/config/settings.py. The only caller that decides
whether this module runs at all is asl_service.build_asl_from_spec();
every other call site is unaffected by this module existing.

Generation moves to the LLM here, but CHECKING stays 100% mechanical:
every candidate is run through the exact same
asl_service.validate_asl() the deterministic translator's output is
held to (structural, reachability, spec consistency, AWS constraints,
extras). A candidate that fails is fed back its own concrete error
list and re-attempted, up to APISettings.asl_llm_max_attempts times --
the same repair-loop shape enrichment/service.py already uses for
Stage 3.5. If no attempt passes, generate_asl_via_llm raises
AslLlmGenerationError; build_asl_from_spec decides from there whether
to propagate that (mode "llm") or fall back to the mechanical
translator (mode "llm_with_fallback").

The live AWS ValidateStateMachineDefinition call
(validate_asl(..., include_aws_validate=...)) is deliberately skipped
for every in-loop attempt -- retrying against AWS's API up to
asl_llm_max_attempts times per generation would be slow and would burn
real API calls for intermediate, likely-wrong candidates. The
mechanical checks (which run locally, no network) are what decide
accept/reject here. The final candidate still gets the live AWS check
exactly once, for free, because build_asl_from_spec's existing final
validate_asl() call (which this module's caller runs unconditionally,
regardless of which generator produced the ASL) already does it.
"""
from __future__ import annotations

import json

from orchestrator.api.config.settings import get_api_settings
from orchestrator.api.services.llm_trace import llm_stage
from orchestrator.indexing.gateway_client import chat_completion

from orchestrator.api.services.asl_generation.prompts import (
    ASL_GENERATION_SYSTEM_PROMPT,
)

# How many issues from a failed validate_asl() report to quote back to
# the model. Unbounded would work too, but a long list tends to make
# the model chase the least important item first; the same cap
# (validate_asl's own issue list has no cap) keeps the repair message
# focused on the first handful of concrete problems.
_MAX_ISSUES_IN_FEEDBACK = 8


class AslLlmGenerationError(Exception):
    """Raised when the LLM couldn't produce ASL that passes the
    mechanical validate_asl() checks within the configured attempt
    budget. Callers that want the old (mechanical) behavior on failure
    should catch this -- see asl_service.build_asl_from_spec's
    "llm_with_fallback" branch.
    """


def _strip_code_fences(text: str) -> str:
    """Mirrors enrichment/service.py's helper of the same name. Kept as
    a local copy rather than a cross-import from enrichment so this
    module's only real dependency is the LLM-JSON-response pattern the
    two stages happen to share, not enrichment itself.
    """
    text = text.strip()
    if text.startswith("```"):
        lines = text.split("\n")
        lines = lines[1:]
        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]
        text = "\n".join(lines).strip()
    return text


def _feedback_from_report(report) -> str:
    issues = report.issues[:_MAX_ISSUES_IN_FEEDBACK]
    if not issues:
        # ok is False but no issues recorded -- e.g. json_ok False from
        # a shape problem validate_asl caught before populating issues.
        return "validate_asl rejected this document but reported no specific issues."
    return "; ".join(f"[{i.group}/{i.code}] {i.message}" for i in issues)


def generate_asl_via_llm(spec: dict) -> tuple[dict, list[str]]:
    """LLM counterpart to asl_service.generate_asl(spec). Same return
    shape -- (asl_dict, generation_notes) -- so build_asl_from_spec can
    call either generator interchangeably.

    Never returns an unvalidated result: raises AslLlmGenerationError
    instead if every attempt is exhausted without a passing candidate.
    """
    # Imported inside the function body, not at module load time:
    # asl_service imports THIS module (for the "llm" / "llm_with_fallback"
    # dispatch branch in build_asl_from_spec), so importing asl_service
    # back at module scope here would be a circular import. By the time
    # this function actually runs, asl_service has finished importing.
    from orchestrator.api.services.asl_service import (
        render_asl_graph,
        sanitize_asl_literals,
        validate_asl,
    )

    settings = get_api_settings()
    max_attempts = max(1, settings.asl_llm_max_attempts)

    messages = [
        {"role": "system", "content": ASL_GENERATION_SYSTEM_PROMPT},
        {"role": "user", "content": json.dumps(spec)},
    ]
    last_error = "unknown error"

    with llm_stage("asl_generation_llm"):
        for attempt in range(1, max_attempts + 1):
            raw = chat_completion(messages, temperature=0)
            cleaned = _strip_code_fences(raw)

            try:
                candidate = json.loads(cleaned)
            except json.JSONDecodeError as exc:
                last_error = f"Response was not valid JSON: {exc}"
                messages.append({"role": "assistant", "content": raw})
                messages.append(
                    {
                        "role": "user",
                        "content": f"Error: {last_error}. Return the complete "
                        "corrected ASL JSON document only.",
                    }
                )
                continue

            if (
                not isinstance(candidate, dict)
                or "States" not in candidate
                or "StartAt" not in candidate
            ):
                last_error = (
                    "Response must be a single JSON object with top-level "
                    "'StartAt' and 'States' fields."
                )
                messages.append({"role": "assistant", "content": raw})
                messages.append(
                    {
                        "role": "user",
                        "content": f"Error: {last_error}. Return the complete "
                        "corrected ASL JSON document only.",
                    }
                )
                continue

            # Same code-level normalization build_asl_from_spec applies to
            # ANY generator's output before judging it -- not another LLM
            # call. Applying it here too (rather than only after this
            # function returns) means the accept/reject decision below
            # matches what the caller will see, instead of failing
            # attempts on something the post-processing pass would have
            # fixed for free anyway.
            candidate = sanitize_asl_literals(candidate)
            graph_dot = render_asl_graph(candidate)
            report = validate_asl(
                candidate, spec=spec, graph_dot=graph_dot, include_aws_validate=False
            )

            if report.ok:
                return candidate, [
                    f"ASL generated by LLM ({attempt} attempt"
                    f"{'s' if attempt > 1 else ''})."
                ]

            last_error = _feedback_from_report(report)
            messages.append({"role": "assistant", "content": raw})
            messages.append(
                {
                    "role": "user",
                    "content": (
                        f"Error: the ASL above failed validation: {last_error}. "
                        "Return the complete corrected ASL JSON document, "
                        "fixing these issues -- not a patch, not an "
                        "explanation, the full document."
                    ),
                }
            )

    raise AslLlmGenerationError(
        f"LLM ASL generation failed after {max_attempts} attempts. "
        f"Last error: {last_error}"
    )